public static int findSmallestInteger(int n) {
    if (n < 10) {
        return -1;
    }
    int smallest = n;
    int[] digits = new int[n];
    for (int i = 0; i < n; i++) {
        digits[i] = n % 10;
        n /= 10;
    }
    Arrays.sort(digits);
    do {
        int curr = 0;
        for (int i = 0; i < n; i++) {
            curr *= 10;
            curr += digits[i];
        }
        if (curr > smallest) {
            smallest = curr;
        }
    } while (nextPermutation(digits));
    return smallest;
}

private static boolean nextPermutation(int[] digits) {
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return false;
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    swap(digits, i, j);
    reverse(digits, i + 1, digits.length - 1);
    return true;
}

private static void swap(int[] digits, int i, int j) {
    int temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
}

private static void reverse(int[] digits, int start, int end) {
    int i = start, j = end;
    while (i < j) {
        swap(digits, i, j);
        i++;
        j--;
    }
}
